    {
      "dataset": "disputes",
      "description": "دعاوی و اختلافات به تفکیک نوع و وضعیت",
      "dimensions": [
        "case_type",
        "status",
        "month"
      ],
      "measures": [
        "count",
        "exposure_m"
      ]
    }
